SELECT 
FROM fund_plan_detail


        AND plan_id = #{params.planId}


        AND business_type = #{params.businessType}


        AND execution_status = #{params.executionStatus}


        AND planned_date >= #{params.startDate}


        AND planned_date <= #{params.endDate}


ORDER BY planned_date ASC, create_time DESC

SELECT 
FROM fund_plan_detail
WHERE plan_id = #{planId}
AND planned_date >= #{startDate} AND planned_date <= #{endDate}
ORDER BY planned_date ASC

SELECT 
FROM fund_plan_detail
WHERE plan_id = #{planId} AND execution_status = 'EXECUTED'

    AND actual_date >= #{startDate}


    AND actual_date <= #{endDate}

ORDER BY actual_date DESC

SELECT 
FROM fund_plan_detail
WHERE plan_id = #{planId} 
AND execution_status = 'EXECUTED'
AND ABS(variance_rate) >= #{varianceThreshold}
ORDER BY ABS(variance_rate) DESC

SELECT COUNT(*)
FROM fund_plan_detail


        AND plan_id = #{params.planId}


        AND business_type = #{params.businessType}


        AND execution_status = #{params.executionStatus}

SELECT COALESCE(SUM(planned_amount), 0)
FROM fund_plan_detail


        AND plan_id = #{params.planId}


        AND business_type = #{params.businessType}


        AND execution_status = #{params.executionStatus}

SELECT COALESCE(SUM(actual_amount), 0)
FROM fund_plan_detail
WHERE execution_status = 'EXECUTED'

    AND plan_id = #{params.planId}


    AND business_type = #{params.businessType}

SELECT COALESCE(SUM(variance_amount), 0)
FROM fund_plan_detail
WHERE execution_status = 'EXECUTED'

    AND plan_id = #{params.planId}


    AND business_type = #{params.businessType}

SELECT COALESCE(AVG(execution_rate), 0)
FROM fund_plan_detail
WHERE execution_status = 'EXECUTED'

    AND plan_id = #{params.planId}


    AND business_type = #{params.businessType}

SELECT COUNT(*) as totalCount, COALESCE(SUM(planned_amount), 0) as totalPlannedAmount, COALESCE(SUM(CASE WHEN execution_status = 'EXECUTED' THEN actual_amount ELSE 0 END), 0) as totalActualAmount, COALESCE(SUM(CASE WHEN execution_status = 'EXECUTED' THEN variance_amount ELSE 0 END), 0) as totalVarianceAmount, COALESCE(AVG(CASE WHEN execution_status = 'EXECUTED' THEN execution_rate ELSE NULL END), 0) as avgExecutionRate, COUNT(CASE WHEN execution_status = 'PENDING' THEN 1 END) as pendingCount, COUNT(CASE WHEN execution_status = 'EXECUTED' THEN 1 END) as executedCount FROM fund_plan_detail
AND plan_id = #{params.planId}
AND business_type = #{params.businessType}
AND execution_status = #{params.executionStatus}
